import{_ as e,o as d,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const l=JSON.parse('{"title":"frontmatter 필드","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/ref-frontmatter"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/ref-frontmatter"}],["meta",{"property":"og:title","content":"frontmatter 필드"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/ref-frontmatter.md","filePath":"docs/ref-frontmatter.md"}'),a={name:"docs/ref-frontmatter.md"};function c(n,t,i,s,h,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="frontmatter-필드" tabindex="-1">frontmatter 필드 <a class="header-anchor" href="#frontmatter-필드" aria-label="Permalink to &quot;frontmatter 필드&quot;">​</a></h1><p>사람이 쓰는 필드와 디스패처·엔진이 쓰는 필드는 갈립니다(<a href="/docs/states">티켓이 지나는 상태</a>가 이미 그 경계를 세웠습니다). 사람이 쓰는 필드에 엔진 쪽 값을 미리 채워 넣으면 안 됩니다. <code>session_id:</code>를 채워두면 이미 할당된 티켓으로 보이고, 그러면 어떤 워커도 그 티켓을 집어 가지 않습니다.</p><h2 id="사람이-쓰는-필드" tabindex="-1">사람이 쓰는 필드 <a class="header-anchor" href="#사람이-쓰는-필드" aria-label="Permalink to &quot;사람이 쓰는 필드&quot;">​</a></h2><table tabindex="0"><thead><tr><th>필드</th><th>필수</th><th>뜻</th></tr></thead><tbody><tr><td><code>ticket</code></td><td>✓</td><td>해시. 파일명과 같게 둡니다(없으면 파일명에서 땁니다)</td></tr><tr><td><code>title</code></td><td>✓</td><td>사람이 읽는 제목</td></tr><tr><td><code>kind</code></td><td></td><td><code>work</code>=지시 / <code>request</code>=부탁 / <code>feedback</code>=결과보고. 표시용이고 값을 강제하지 않습니다</td></tr><tr><td><code>persona</code></td><td></td><td>수행할 페르소나 이름. 없으면 페르소나 없는 평범한 에이전트가 처리합니다. 알파벳·숫자·<code>-</code>·<code>_</code>만 통과합니다</td></tr><tr><td><code>deps</code></td><td></td><td><code>[&lt;hash&gt;...]</code> 하드 선후. 전부 완료여야 큐에 뜹니다</td></tr></tbody></table><h2 id="디스패처·엔진이-쓰는-필드" tabindex="-1">디스패처·엔진이 쓰는 필드 <a class="header-anchor" href="#디스패처·엔진이-쓰는-필드" aria-label="Permalink to &quot;디스패처·엔진이 쓰는 필드&quot;">​</a></h2><table tabindex="0"><thead><tr><th>필드</th><th>쓰는 시점</th><th>뜻</th></tr></thead><tbody><tr><td><code>session_id</code></td><td><code>assign</code> — 엔진을 띄우기 <strong>전</strong></td><td>있으면 할당된 것으로 보고 큐에서 제외합니다. 판정이 보는 값은 이것 하나뿐입니다</td></tr><tr><td><code>assigned_at</code></td><td><code>assign</code>과 동시</td><td>할당 시각(reap의 유예 판정에 쓰입니다)</td></tr><tr><td><code>owner</code></td><td><code>assign</code>(자동 디스패치) 또는 <code>handclaim</code>(손 클레임)</td><td>자동이면 <code>&lt;페르소나 또는 agent&gt; / &lt;워커&gt;-&lt;sid 앞8자리&gt;</code>, 손 클레임이면 호출자가 준 식별자</td></tr><tr><td><code>pid</code></td><td><code>setpid</code> — 엔진을 백그라운드로 띄운 <strong>뒤</strong>, 또는 <code>handclaim</code>이 조상 <code>claude</code> pid를 기록</td><td>생존 확인용. 큐 제외 판정과는 상관이 없습니다</td></tr><tr><td><code>inbox</code></td><td><code>setinbox</code> — 최초 프롬프트 주입이 끝난 <strong>뒤</strong></td><td>참견 FIFO 경로. FIFO 파일은 세션이 끝나면 사라지지만 이 값 자체는 정상 완료나 자동 스테일 회수로는 안 지워집니다. <code>unassign</code>이나 디스패치 실패로만 비워집니다</td></tr><tr><td><code>claimed_at</code></td><td><code>handclaim</code></td><td>손으로 잡은 시각(유휴 판정 유예에 쓰입니다)</td></tr><tr><td><code>transcript</code></td><td><code>handclaim</code></td><td>그 순간 가장 최근 트랜스크립트 경로(유휴 판정용)</td></tr><tr><td><code>attempts</code></td><td><code>reap</code>(회수할 때마다 증가)</td><td>자동 회수 2회까지 세고, 답변 요청으로 전환되면 <code>0</code>으로 리셋됩니다</td></tr><tr><td><code>awaiting</code></td><td><code>reap</code>이 답변 요청으로 올릴 때(자동 회수 3회째, 또는 본문 마지막 절이 <code>## 블록</code>이면 횟수 무관 즉시)</td><td>존재하지 않는 해시. <code>deps</code>처럼 걸려 큐를 잠급니다. 같은 이름의 답변 파일(<code>&lt;awaiting&gt;.done.md</code>)이 생기면 저절로 풀립니다</td></tr></tbody></table>',6)])])}const g=e(a,[["render",c]]);export{l as __pageData,g as default};
